-- ============================================================
-- HoneyDesk (Mifang) 跨境电商数据模型 V2 - 建表 + 丰富种子数据
-- 维度: 多店铺/多市场/多仓库/多渠道/多语言/多币种
-- DDL 由 ORM 模型自动生成, 保证与后端字段一致
-- ============================================================
CREATE DATABASE IF NOT EXISTS honey_desk DEFAULT CHARSET utf8mb4;
CREATE DATABASE IF NOT EXISTS honey_system DEFAULT CHARSET utf8mb4;
USE honey_system;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

DROP TABLE IF EXISTS `honey_system`.`stores`;
CREATE TABLE `honey_system`.`stores` (
  `id` VARCHAR(40) NOT NULL,
  `name` VARCHAR(120) NOT NULL,
  `platform` VARCHAR(40) NOT NULL,
  `market` VARCHAR(40) NOT NULL,
  `market_group` VARCHAR(20) NOT NULL,
  `currency` VARCHAR(6) NOT NULL,
  `timezone` VARCHAR(40) NOT NULL,
  `active` BOOL NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (`id`)
);

DROP TABLE IF EXISTS `honey_desk`.`products`;
CREATE TABLE `honey_desk`.`products` (
  `id` VARCHAR(40) NOT NULL,
  `store_id` VARCHAR(40) NOT NULL,
  `name` VARCHAR(200) NOT NULL,
  `category` VARCHAR(80) NOT NULL,
  `sub_category` VARCHAR(80) NOT NULL,
  `brand` VARCHAR(80) NOT NULL,
  `series` VARCHAR(80) NOT NULL,
  `price` FLOAT NOT NULL,
  `cost` FLOAT NOT NULL,
  `weight_g` FLOAT NOT NULL,
  `volume_cm3` FLOAT NOT NULL,
  `asin` VARCHAR(24) NOT NULL,
  `barcode` VARCHAR(40) NOT NULL,
  `launch_date` DATE,
  `case_size` INTEGER NOT NULL,
  `status` VARCHAR(20) NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (`id`)
);

DROP TABLE IF EXISTS `honey_desk`.`product_materials`;
CREATE TABLE `honey_desk`.`product_materials` (
  `id` INTEGER NOT NULL AUTO_INCREMENT,
  `store_id` VARCHAR(40) NOT NULL,
  `sku` VARCHAR(40) NOT NULL,
  `name` VARCHAR(200) NOT NULL,
  `target_market` VARCHAR(40) NOT NULL,
  `target_language` VARCHAR(20) NOT NULL,
  `category` VARCHAR(80) NOT NULL,
  `sub_category` VARCHAR(80) NOT NULL,
  `brand` VARCHAR(80) NOT NULL,
  `series` VARCHAR(80) NOT NULL,
  `features` TEXT NOT NULL,
  `usage_text` TEXT NOT NULL,
  `materials` TEXT NOT NULL,
  `selling_points` TEXT NOT NULL,
  `target_audience` TEXT NOT NULL,
  `keywords` TEXT NOT NULL,
  `spec` TEXT NOT NULL,
  `net_weight_g` FLOAT NOT NULL,
  `expiry_days` INTEGER NOT NULL,
  `certifications` TEXT NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (`id`)
);

DROP TABLE IF EXISTS `honey_desk`.`listings`;
CREATE TABLE `honey_desk`.`listings` (
  `id` INTEGER NOT NULL AUTO_INCREMENT,
  `store_id` VARCHAR(40) NOT NULL,
  `sku` VARCHAR(40) NOT NULL,
  `market` VARCHAR(40) NOT NULL,
  `platform` VARCHAR(20) NOT NULL,
  `language` VARCHAR(20) NOT NULL,
  `title` VARCHAR(400) NOT NULL,
  `bullet_points` JSON NOT NULL,
  `description` TEXT NOT NULL,
  `search_terms` TEXT NOT NULL,
  `version` INTEGER NOT NULL,
  `status` VARCHAR(20) NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (`id`)
);

DROP TABLE IF EXISTS `honey_desk`.`sales_orders`;
CREATE TABLE `honey_desk`.`sales_orders` (
  `id` VARCHAR(40) NOT NULL,
  `store_id` VARCHAR(40) NOT NULL,
  `sku` VARCHAR(40) NOT NULL,
  `order_date` DATE NOT NULL,
  `market` VARCHAR(10) NOT NULL,
  `channel` VARCHAR(30) NOT NULL,
  `platform` VARCHAR(30) NOT NULL,
  `currency` VARCHAR(6) NOT NULL,
  `quantity` INTEGER NOT NULL,
  `unit_price` FLOAT NOT NULL,
  `revenue` FLOAT NOT NULL,
  `shipping_fee` FLOAT NOT NULL,
  `fulfillment` VARCHAR(20) NOT NULL,
  `order_status` VARCHAR(20) NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (`id`)
);

DROP TABLE IF EXISTS `honey_desk`.`competitors`;
CREATE TABLE `honey_desk`.`competitors` (
  `id` INTEGER NOT NULL AUTO_INCREMENT,
  `store_id` VARCHAR(40) NOT NULL,
  `sku` VARCHAR(40) NOT NULL,
  `market` VARCHAR(10) NOT NULL,
  `platform` VARCHAR(30) NOT NULL,
  `competitor_name` VARCHAR(120) NOT NULL,
  `competitor_sku` VARCHAR(40) NOT NULL,
  `price` FLOAT NOT NULL,
  `snapshot_date` DATE NOT NULL,
  `stock` INTEGER,
  `out_of_stock` BOOL NOT NULL,
  `rating` FLOAT,
  `review_count` INTEGER NOT NULL,
  `monthly_sales` INTEGER NOT NULL,
  `listing_days` INTEGER NOT NULL,
  `price_trend` VARCHAR(10) NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (`id`)
);

DROP TABLE IF EXISTS `honey_desk`.`inventory`;
CREATE TABLE `honey_desk`.`inventory` (
  `id` INTEGER NOT NULL AUTO_INCREMENT,
  `store_id` VARCHAR(40) NOT NULL,
  `sku` VARCHAR(40) NOT NULL,
  `market` VARCHAR(10) NOT NULL,
  `warehouse` VARCHAR(60) NOT NULL,
  `warehouse_name` VARCHAR(120) NOT NULL,
  `warehouse_type` VARCHAR(20) NOT NULL,
  `region` VARCHAR(20) NOT NULL,
  `available` INTEGER NOT NULL,
  `in_transit` INTEGER NOT NULL,
  `reserved` INTEGER NOT NULL,
  `damaged` INTEGER NOT NULL,
  `safety_stock` INTEGER NOT NULL,
  `reorder_point` INTEGER NOT NULL,
  `stock_valuation` FLOAT NOT NULL,
  `days_of_supply` INTEGER NOT NULL,
  `avg_daily_sales` FLOAT NOT NULL,
  `last_inbound_at` DATE,
  `replenish_lead_days` INTEGER NOT NULL,
  `bin_location` VARCHAR(40) NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (`id`)
);

DROP TABLE IF EXISTS `honey_desk`.`ad_performance`;
CREATE TABLE `honey_desk`.`ad_performance` (
  `id` INTEGER NOT NULL AUTO_INCREMENT,
  `store_id` VARCHAR(40) NOT NULL,
  `sku` VARCHAR(40) NOT NULL,
  `market` VARCHAR(10) NOT NULL,
  `platform` VARCHAR(30) NOT NULL,
  `campaign` VARCHAR(120) NOT NULL,
  `ad_group` VARCHAR(80) NOT NULL,
  `target_type` VARCHAR(20) NOT NULL,
  `match_type` VARCHAR(20) NOT NULL,
  `stat_date` DATE NOT NULL,
  `currency` VARCHAR(6) NOT NULL,
  `spend` FLOAT NOT NULL,
  `sales` FLOAT NOT NULL,
  `ad_sku_sales` FLOAT NOT NULL,
  `clicks` INTEGER NOT NULL,
  `impressions` INTEGER NOT NULL,
  `orders` INTEGER NOT NULL,
  `ctr` FLOAT NOT NULL,
  `cpc` FLOAT NOT NULL,
  `acos` FLOAT NOT NULL,
  `roas` FLOAT NOT NULL,
  `status` VARCHAR(20) NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (`id`)
);

DROP TABLE IF EXISTS `honey_desk`.`ad_budgets`;
CREATE TABLE `honey_desk`.`ad_budgets` (
  `id` INTEGER NOT NULL AUTO_INCREMENT,
  `store_id` VARCHAR(40) NOT NULL,
  `sku` VARCHAR(40) NOT NULL,
  `market` VARCHAR(10) NOT NULL,
  `platform` VARCHAR(30) NOT NULL,
  `budget_period` VARCHAR(20) NOT NULL,
  `budget_type` VARCHAR(20) NOT NULL,
  `currency` VARCHAR(6) NOT NULL,
  `bid` FLOAT NOT NULL,
  `daily_budget` FLOAT NOT NULL,
  `monthly_budget` FLOAT NOT NULL,
  `spent` FLOAT NOT NULL,
  `target_acos` FLOAT NOT NULL,
  `status` VARCHAR(20) NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
  PRIMARY KEY (`id`)
);

CREATE INDEX `ix_products_store_id` ON `honey_desk`.`products` (`store_id`);
CREATE INDEX `ix_product_materials_store_id` ON `honey_desk`.`product_materials` (`store_id`);
CREATE INDEX `ix_product_materials_sku` ON `honey_desk`.`product_materials` (`sku`);
CREATE INDEX `ix_listings_sku` ON `honey_desk`.`listings` (`sku`);
CREATE INDEX `ix_listings_store_id` ON `honey_desk`.`listings` (`store_id`);
CREATE INDEX `ix_sales_orders_order_date` ON `honey_desk`.`sales_orders` (`order_date`);
CREATE INDEX `ix_sales_orders_sku` ON `honey_desk`.`sales_orders` (`sku`);
CREATE INDEX `ix_sales_orders_store_id` ON `honey_desk`.`sales_orders` (`store_id`);
CREATE INDEX `ix_competitors_store_id` ON `honey_desk`.`competitors` (`store_id`);
CREATE INDEX `ix_competitors_sku` ON `honey_desk`.`competitors` (`sku`);
CREATE INDEX `ix_competitors_snapshot_date` ON `honey_desk`.`competitors` (`snapshot_date`);
CREATE INDEX `ix_inventory_store_id` ON `honey_desk`.`inventory` (`store_id`);
CREATE INDEX `ix_inventory_sku` ON `honey_desk`.`inventory` (`sku`);
CREATE INDEX `ix_ad_performance_sku` ON `honey_desk`.`ad_performance` (`sku`);
CREATE INDEX `ix_ad_performance_stat_date` ON `honey_desk`.`ad_performance` (`stat_date`);
CREATE INDEX `ix_ad_performance_store_id` ON `honey_desk`.`ad_performance` (`store_id`);
CREATE INDEX `ix_ad_budgets_store_id` ON `honey_desk`.`ad_budgets` (`store_id`);
CREATE INDEX `ix_ad_budgets_sku` ON `honey_desk`.`ad_budgets` (`sku`);










SET FOREIGN_KEY_CHECKS=1;